package cn.gmiya.malodylink;
import android.app.*;import android.widget.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class ExtraBoards {
 static JSONObject load(Activity a,Engine engine,String file)throws Exception{
  if(!engine.server.equals(RankConnection.config(a).getString("server")))throw new Exception("服务器不匹配");
  OpenListScoreRemote remote=RankConnection.open(a);JSONObject status=new JSONObject(new String(remote.getPath("/_rankings/v2/status.json",100000),StandardCharsets.UTF_8));String rev=status.getString("revision");if(status.optInt("schema")!=2||!rev.matches("[a-f0-9]{64}"))throw new Exception("榜单版本无效");
  JSONObject doc=new JSONObject(new String(remote.getPath("/_rankings/v2/"+rev+"/"+file,16000000),StandardCharsets.UTF_8));if(doc.optInt("schema")!=2||!engine.server.equals(doc.optString("server"))||!rev.equals(doc.optString("revision")))throw new Exception("榜单身份不匹配");return doc;
 }
 public static void home(Activity a,Engine e,LinearLayout parent){
  LinearLayout card=AppUi.column(a,14);android.graphics.drawable.GradientDrawable surface=AppUi.background(a,AppUi.CARD);surface.setStroke(AppUi.dp(a,1),AppUi.BORDER);card.setBackground(surface);
  LinearLayout top=new LinearLayout(a);top.setGravity(android.view.Gravity.CENTER_VERTICAL);top.addView(AppUi.text(a,"我的活跃度",16,AppUi.INK,true),new LinearLayout.LayoutParams(0,-2,1));
  ImageButton refresh=new ImageButton(a);refresh.setImageDrawable(new NavIcon(4,AppUi.ACCENT));refresh.setContentDescription("刷新我的活跃度");refresh.setTooltipText("刷新我的活跃度");refresh.setPadding(AppUi.dp(a,11),AppUi.dp(a,11),AppUi.dp(a,11),AppUi.dp(a,11));refresh.setBackground(AppUi.background(a,AppUi.SELECTED));top.addView(refresh,new LinearLayout.LayoutParams(AppUi.dp(a,44),AppUi.dp(a,44)));card.addView(top);AppUi.space(card,8);
  LinearLayout metrics=new LinearLayout(a);metrics.setGravity(android.view.Gravity.TOP);String[] labels={"今日","近30天","累计"};TextView[] values=new TextView[3];for(int i=0;i<3;i++){LinearLayout cell=AppUi.column(a,8);if(i==0)cell.setBackground(AppUi.background(a,AppUi.SELECTED));cell.addView(AppUi.text(a,labels[i],12,i==0?AppUi.ACCENT:AppUi.MUTED,false));values[i]=number(a,i==0?26:22);cell.addView(values[i],new LinearLayout.LayoutParams(-1,-2));cell.addView(AppUi.text(a,"次",12,AppUi.MUTED,false));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);if(i>0)cp.leftMargin=AppUi.dp(a,6);metrics.addView(cell,cp);}TextView nToday=values[0],nMonth=values[1],nTotal=values[2];card.addView(metrics);AppUi.space(card,8);TextView hint=AppUi.text(a,"云端有效游玩记录 · 正在更新",12,AppUi.MUTED,false);card.addView(hint);parent.addView(card,new LinearLayout.LayoutParams(-1,-2));AppUi.space(parent,14);
  Runnable fetch=()->{String qq=ScoreStore.profile(a);if(qq.isEmpty()){hint.setText("设置QQ并同步云端后查看活跃度");return;}refresh.setEnabled(false);hint.setText("正在更新云端记录…");new Thread(()->{JSONObject me=null;boolean ok=false;try{JSONArray rows=load(a,e,"activity.json").getJSONArray("players");for(int i=0;i<rows.length();i++)if(qq.equals(rows.getJSONObject(i).optString("qq")))me=rows.getJSONObject(i);ok=true;}catch(Exception ignored){}final JSONObject current=me;final boolean success=ok;a.runOnUiThread(()->{if(a.isDestroyed())return;refresh.setEnabled(true);if(success){nToday.setText(String.format(Locale.ROOT,"%,d",current==null?0:current.optLong("today")));nMonth.setText(String.format(Locale.ROOT,"%,d",current==null?0:current.optLong("month")));nTotal.setText(String.format(Locale.ROOT,"%,d",current==null?0:current.optLong("total")));hint.setText("云端去重记录 · 今日按北京时间统计");}else hint.setText("更新未完成，点刷新重试");});}).start();};refresh.setOnClickListener(v->fetch.run());fetch.run();
 }
 private static TextView number(Activity a,int size){TextView n=AppUi.text(a,"—",size,AppUi.INK,true);n.setSingleLine(true);n.setAutoSizeTextTypeUniformWithConfiguration(12,size,1,android.util.TypedValue.COMPLEX_UNIT_SP);return n;}
 public static JSONArray ranked(JSONObject doc,String key)throws Exception{
  JSONArray input=doc.getJSONArray("players");List<JSONObject> rows=new ArrayList<>();Set<String> seen=new HashSet<>();if(input.length()>10000)throw new Exception("榜单过大");
  for(int i=0;i<input.length();i++){JSONObject r=input.getJSONObject(i);String qq=r.getString("qq");double value=r.getDouble(key);if(!qq.matches("[1-9][0-9]{4,11}")||!seen.add(qq)||!Double.isFinite(value)||value<0)throw new Exception("榜单数据无效");if(value>0)rows.add(new JSONObject(r.toString()).put("plays",r.optLong(key)));}
  rows.sort((x,y)->{int r=Double.compare(y.optDouble(key),x.optDouble(key));return r!=0?r:x.optString("qq").compareTo(y.optString("qq"));});JSONArray out=new JSONArray();int rank=0;double before=-1;for(int i=0;i<rows.size();i++){JSONObject r=rows.get(i);double value=r.getDouble(key);if(value!=before)rank=i+1;before=value;out.put(r.put("rank",rank));}return out;
 }
 public static void show(Activity a,Engine e,int mode){String title=mode==2?"6K rating 排行 · O20+N10":mode==1?"近30天活跃榜":"累计活跃榜";TextView content=AppUi.text(a,"正在读取云端…",16,AppUi.INK,false);content.setPadding(24,16,24,16);ScrollView scroll=new ScrollView(a);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setPositiveButton("关闭",null).show();new Thread(()->{String result;try{JSONObject doc=load(a,e,mode==2?"6k.json":"activity.json");JSONArray array=doc.getJSONArray("players");List<JSONObject> rows=new ArrayList<>();String key=mode==2?"rating":mode==1?"month":"total";for(int i=0;i<array.length();i++){JSONObject r=array.getJSONObject(i);double v=r.getDouble(key);if(!Double.isFinite(v)||v<0)throw new Exception();if(v>0)rows.add(r);}rows.sort((x,y)->{int r=Double.compare(y.optDouble(key),x.optDouble(key));return r!=0?r:x.optString("qq").compareTo(y.optString("qq"));});StringBuilder text=new StringBuilder(mode==2?"仅计算6K，缺位按0计\n\n":"按云端去重游玩记录，今日以北京时间计算\n\n");int rank=0;double previous=-1;for(int i=0;i<rows.size();i++){JSONObject r=rows.get(i);double value=r.getDouble(key);if(value!=previous)rank=i+1;previous=value;text.append(rank).append(". ").append(r.optString("name","玩家")).append(" · ").append(mode==2?String.format(Locale.ROOT,"%.4f",value):String.format(Locale.ROOT,"%.0f次",value)).append("\n\n");}result=rows.isEmpty()?"暂无云端记录":text.toString();}catch(Exception ex){result="榜单暂不可用，请稍后重试";}String text=result;a.runOnUiThread(()->{if(!a.isDestroyed()&&dialog.isShowing())content.setText(text);});}).start();}
}
